import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` per-line config text.

    Each line is split on its first "=", and whitespace around the name and
    the value is stripped. Blank lines, lines starting with "#", and lines
    without "=" are ignored. Values may contain "=". If the key appears more
    than once, the first occurrence wins. Returns "" when the key is absent.
    The key is matched exactly (case-sensitive). No files are read.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, val = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return val.strip()
    return ""


def test_basic_lookup() -> None:
    assert config_value("a=1\nb=2", "b") == "2"
    assert config_value("a=1\nb=2", "a") == "1"


def test_missing_key_returns_empty() -> None:
    assert config_value("a=1\nb=2", "c") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_empty_value_is_empty_string() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_whitespace_stripped() -> None:
    assert config_value("  name  =  hello world  \n", "name") == "hello world"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?a=b", "url") == "http://x/?a=b"


def test_comments_and_blank_lines_ignored() -> None:
    text = "# a=1\n\n   \nb=2\n"
    assert config_value(text, "a") == ""
    assert config_value(text, "b") == "2"


def test_lines_without_equals_ignored() -> None:
    assert config_value("junk\na=1", "junk") == ""
    assert config_value("junk\na=1", "a") == "1"


def test_duplicate_key_first_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_key_is_case_sensitive() -> None:
    assert config_value("Key=v", "key") == ""
    assert config_value("Key=v", "Key") == "v"


def test_key_must_match_exactly() -> None:
    assert config_value("abc=1", "ab") == ""
    assert config_value("ab=1", "abc") == ""


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


def test_no_trailing_newline() -> None:
    assert config_value("a=1", "a") == "1"


@pytest.mark.parametrize("key", ["", " "])
def test_empty_key_not_found_in_normal_text(key: str) -> None:
    assert config_value("a=1", key) == ""

